def run(app, request="r"):
    """Send one request through app on a fresh trace; return (response, trace)."""
    log.clear()
    response = app(request)
    return response, list(log)
def escapes(app, request="r"):
    """Send one request through app; return (name of the exception that escaped, trace)."""
    log.clear()
    try:
        app(request)
    except Exception as error:
        return type(error).__name__, list(log)
