def compose(middlewares, handler):
    layers = list(middlewares)                  # a snapshot: the caller's list is never touched

    def app(request):
        def dispatch(position, request):
            if position == len(layers):
                return handler(request)
            # next() for this layer runs the layer after it; the position lives in this closure, not in shared state
            return layers[position](request, lambda next_request: dispatch(position + 1, next_request))

        return dispatch(0, request)

    return app
